            ["Open the notification center to read it."] = ("Abre el centro de notificaciones para leerla.", "Buka pusat notifikasi untuk membacanya.", "打开通知中心查看。"),
            ["Alerts from NabyScape and your other apps will show up here."] = ("Aquí aparecerán los avisos de NabyScape y de tus otras apps.", "Notifikasi dari NabyScape dan aplikasi lain akan muncul di sini.", "NabyScape 和其他应用的提醒将显示在这里。"),
            ["Notifications from other apps"] = ("Notificaciones de otras apps", "Notifikasi dari aplikasi lain", "来自其他应用的通知"),
            ["Welcome"] = ("Bienvenida", "Selamat datang", "欢迎"),
            ["Welcome to NabyScape"] = ("Bienvenido a NabyScape", "Selamat datang di NabyScape", "欢迎使用 NabyScape"),
            ["Make the dock yours."] = ("Haz tuyo el dock.", "Jadikan dock milikmu.", "打造属于你的 dock。"),
