            ["Download updates automatically"] = ("Descargar actualizaciones automáticamente", "Unduh pembaruan otomatis", "自动下载更新"),
            ["Check for a release, download it, then choose when to install and restart."] = ("Busca una versión, descárgala y elige cuándo instalar y reiniciar.", "Periksa rilis, unduh, lalu pilih kapan memasang dan memulai ulang.", "检查新版本并下载，再自行选择何时安装和重启。"),
            ["Check once at normal startup when the last attempt was at least 24 hours ago."] = ("Comprueba al iniciar si han pasado al menos 24 horas desde el último intento.", "Periksa saat mulai jika upaya terakhir setidaknya 24 jam yang lalu.", "正常启动时，若距上次检查已超过 24 小时则检查一次。"),
            ["Automatic downloads are optional and may use a metered connection. They follow automatic startup checks; installation always waits for you."] = ("Las descargas automáticas son opcionales y pueden usar una conexión medida. Siguen las comprobaciones al inicio; la instalación siempre espera tu decisión.", "Unduhan otomatis opsional dan dapat memakai koneksi berbayar. Unduhan mengikuti pemeriksaan saat mulai; pemasangan selalu menunggu Anda.", "自动下载为可选项，可能使用按流量计费的网络。它跟随启动时的自动检查；安装始终等你确认。"),
            ["Restore the previous app and its saved settings? Changes to settings and JSON profile data since that backup will be replaced. Local media files are kept."] = ("¿Restaurar la aplicación anterior y sus ajustes? Se reemplazarán los cambios de ajustes y perfiles JSON desde esa copia. Se conservarán los archivos multimedia locales.", "Pulihkan aplikasi sebelumnya dan pengaturan tersimpan? Perubahan pengaturan dan data profil JSON sejak cadangan akan diganti. Berkas media lokal dipertahankan.", "恢复上一个版本及其保存的设置？自该备份以来的设置和 JSON 配置数据更改将被替换。本地媒体文件会保留。"),
            ["Restore previous version"] = ("Restaurar versión anterior", "Pulihkan versi sebelumnya", "恢复上一版本"),
            ["Download the official setup for this app's architecture and verify its size, version and SHA-256."] = ("Descarga el instalador oficial para esta arquitectura y verifica su tamaño, versión y SHA-256.", "Unduh pemasang resmi untuk arsitektur aplikasi ini dan verifikasi ukuran, versi, serta SHA-256.", "下载与当前应用架构匹配的官方安装包，并验证其大小、版本和 SHA-256。"),
            ["Save, create a recovery copy, install the verified update and reopen NabyScape."] = ("Guarda, crea una copia de recuperación, instala la actualización verificada y vuelve a abrir NabyScape.", "Simpan, buat salinan pemulihan, pasang pembaruan terverifikasi, dan buka kembali NabyScape.", "保存并创建恢复副本，安装已验证的更新，然后重新打开 NabyScape。"),
            ["Downloads use official GitHub releases. SHA-256 checks integrity; unsigned checksums do not establish publisher identity. Windows security checks remain enabled."] = ("Las descargas usan versiones oficiales de GitHub. SHA-256 comprueba la integridad; las sumas sin firma no acreditan al editor. Los controles de seguridad de Windows siguen activos.", "Unduhan memakai rilis GitHub resmi. SHA-256 memeriksa integritas; checksum tanpa tanda tangan tidak membuktikan identitas penerbit. Pemeriksaan keamanan Windows tetap aktif.", "下载使用官方 GitHub 发布版。SHA-256 用于校验完整性；未签名的校验和不能证明发布者身份。Windows 安全检查保持启用。"),
            ["Checks run only when you request them. A chat check sends one short message and may use provider credits; Hermes processes it as an agent message. Setup never opens the microphone or downloads models automatically."] = ("Las comprobaciones se ejecutan solo cuando las solicitas. Comprobar el chat envía un mensaje breve y puede usar créditos; Hermes lo procesa como mensaje de agente. La configuración nunca abre el micrófono ni descarga modelos automáticamente.", "Pemeriksaan hanya berjalan saat diminta. Pemeriksaan obrolan mengirim satu pesan singkat dan dapat memakai kredit penyedia; Hermes memprosesnya sebagai pesan agen. Penyiapan tidak pernah membuka mikrofon atau mengunduh model otomatis.", "检查仅在您主动发起时运行。聊天检查会发送一条短消息，可能消耗服务商额度；Hermes 会将其作为代理消息处理。设置过程绝不会自动打开麦克风或下载模型。"),
            // ——— 覆盖补全批次 1：通用与设置窗口（西/印尼暂空，回退英文） ———
            ["A little space. More possibilities."] = ("", "", "一点空间，更多可能。"),
            ["Activity"] = ("", "", "活动"),
            ["Add another provider, or choose which saved connection to edit."] = ("", "", "添加其他服务商，或选择要编辑的已保存连接。"),
            ["Add files…"] = ("", "", "添加文件…"),
            ["Add local event"] = ("", "", "添加本地日程"),
            ["Add selected app"] = ("", "", "添加所选应用"),
            ["Add to shelf"] = ("", "", "添加到文件架"),
            ["Album cover"] = ("", "", "专辑封面"),
            ["All tools"] = ("", "", "全部工具"),
            ["All tools are hidden. Enable them in Settings → Widgets."] = ("", "", "全部工具已隐藏。可在“设置 → 小组件”中启用。"),
            ["All widgets remain available in Settings. Weather asks for a city; AI asks for a connection."] = ("", "", "所有小组件都保留在设置中。天气需要选择城市，AI 需要配置连接。"),
            ["Allow the window/display images I choose to share"] = ("", "", "允许共享我选择的窗口/屏幕图像"),
            ["Animations follow the Windows compositor. Actual FPS depends on your display and GPU load."] = ("", "", "动画遵循 Windows 合成器节奏。实际帧率取决于显示器与 GPU 负载。"),
            ["API base URL"] = ("", "", "API 基础地址"),
            ["Apply power plan"] = ("", "", "应用电源计划"),
            ["Artist"] = ("", "", "歌手"),
            ["Artist · media title"] = ("", "", "歌手 · 媒体标题"),
            ["Ask Naby"] = ("", "", "问 Naby"),
            ["Assistant instructions"] = ("", "", "助手指令"),
            ["Audio mixer"] = ("", "", "音频混音器"),
            ["Auto follows your display. Save power reduces update frequency; Smoother motion allows more frequent frames."] = ("", "", "自动跟随显示器。省电模式降低刷新频率；流畅模式允许更高帧率。"),
            ["Back to widgets"] = ("", "", "返回小组件"),
            ["Break minutes"] = ("", "", "休息分钟数"),
            ["Brief previews appear without taking focus or replacing an open panel."] = ("", "", "简要预览不会抢占焦点，也不会替换已打开的面板。"),
            ["Browse…"] = ("", "", "浏览…"),
            ["Capture a thought…"] = ("", "", "记下一个想法…"),
            ["Center"] = ("", "", "居中"),
            ["Chat or talk, right from your island."] = ("", "", "在岛上直接聊天或对话。"),
            ["Checking the connection sends one short message and may use provider credits. Your chat history, microphone and screen are not sent."] = ("", "", "检查连接会发送一条短消息，可能消耗服务商额度。聊天记录、麦克风和屏幕内容不会被发送。"),
            ["Choose a category to reset only its preferences; for example Appearance keeps your current layout."] = ("", "", "选择一个分类仅重置其偏好；例如“外观”会保留当前布局。"),
            ["Choose a city in Weather"] = ("", "", "在天气中选择城市"),
            ["Choose a language, use the suggested models, then Install & use. Nothing downloads until you choose to install."] = ("", "", "选择语言、使用推荐的模型，然后安装并使用。未经确认不会下载任何内容。"),
            ["Choose a location you can write to. Your personal settings are kept separately."] = ("", "", "选择一个你有写入权限的位置。个人设置单独保存。"),
            ["Choose a purpose to change widgets, or keep Recommended to use the complete default setup. Microphone listening starts only when you choose it."] = ("", "", "选择用途以调整小组件，或保持“推荐”使用完整默认配置。麦克风监听仅在您主动选择后开启。"),
            ["Choose a starting point. You can change every choice later."] = ("", "", "选择一个起点。之后所有选择都可以更改。"),
            ["Choose folder…"] = ("", "", "选择文件夹…"),
            ["Choose from the power plans available on this PC."] = ("", "", "从这台电脑可用的电源计划中选择。"),
            ["Choose lyrics provider"] = ("", "", "选择歌词来源"),
            ["NabyScape · AI providers"] = ("", "", "NabyScape · AI 服务商"),
            ["NabyScape · Companion"] = ("", "", "NabyScape · 助手"),
            ["Choose what you want to do. Your saved setup stays available when you switch between chat and voice."] = ("", "", "选择你想做的事。聊天与语音切换时，已保存的配置始终可用。"),
            ["Choose where your voice is processed. Your chat connection supplies the answers."] = ("", "", "选择语音处理位置。回答仍由你的聊天连接提供。"),
            ["Choose who answers your messages. Your connection stays saved on this PC."] = ("", "", "选择由谁回答你的消息。连接配置保存在本机。"),
            ["Cleaned link"] = ("", "", "已清理的链接"),
            ["Cleaned preview · review before copying"] = ("", "", "清理预览 · 复制前请确认"),
            ["Click cover to play"] = ("", "", "点击封面播放"),
            ["Click the dock to open your widgets. Hover for a quick look. Right-click the tray icon to open Settings."] = ("", "", "点击 dock 打开小组件。悬停可快速预览。右键托盘图标打开设置。"),
            ["Closing Settings keeps NabyScape running. Quit from the tray."] = ("", "", "关闭设置后 NabyScape 继续运行。退出请使用系统托盘。"),
            ["Color preview input"] = ("", "", "颜色预览输入"),
            ["Command bar"] = ("", "", "命令栏"),
            ["Compatible API base URL"] = ("", "", "兼容的 API 基础地址"),
            ["Connect an API. Choose how you chat, speak and share context."] = ("", "", "连接 API。选择聊天、语音与上下文共享方式。"),
            ["Controls & outlines"] = ("", "", "控件与描边"),
            ["Copy diagnostics report"] = ("", "", "复制诊断报告"),
            ["Could not copy the report. Try again."] = ("", "", "无法复制报告，请重试。"),
            ["Could not export the report. Try another location."] = ("", "", "无法导出报告，请尝试其他位置。"),
            ["CPU"] = ("", "", "CPU"),
            ["Customize"] = ("", "", "自定义"),
            ["Default: Ctrl+Alt+H. Shows the closed island even over the current maximized or fullscreen app. Switching apps restores automatic hiding."] = ("", "", "默认 Ctrl+Alt+H。即使在当前最大化或全屏应用之上也显示收起的岛。切换应用后恢复自动隐藏。"),
            ["Default: Ctrl+Alt+I. Use Ctrl+K for commands, Ctrl+Tab to switch tabs, and Esc to go back or close. Choose another hotkey if an app already uses it."] = ("", "", "默认 Ctrl+Alt+I。Ctrl+K 打开命令、Ctrl+Tab 切换标签、Esc 返回或关闭。若与其他应用冲突请更换热键。"),
            ["Default: Ctrl+Alt+T. First press tucks to the edge; second returns to automatic rules. Manual hide stays hidden. Choose distinct combinations for panel, visibility and tuck; registration errors appear above."] = ("", "", "默认 Ctrl+Alt+T。第一次按收起到边缘，第二次恢复自动规则。手动隐藏保持隐藏。面板、显示与收起的热键请设置不同的组合；注册错误会显示在上方。"),
            ["Diagnostics preview refreshed."] = ("", "", "诊断预览已刷新。"),
            ["Diagnostics report copied."] = ("", "", "诊断报告已复制。"),
            ["Diagnostics report exported."] = ("", "", "诊断报告已导出。"),
            ["Dismiss"] = ("", "", "忽略"),
            ["Dock position"] = ("", "", "Dock 位置"),
            ["Dots keep your panels easy to reach. Hover over a dot to see its name."] = ("", "", "圆点让各面板触手可及。悬停圆点可查看名称。"),
            ["Drag files onto the island or its tucked edge. Drop to stage references; select multiple shelf items to drag them out together. Manual hiding stays hidden."] = ("", "", "把文件拖到岛上或收起边缘。松开即暂存引用；选中多个文件架条目可一起拖出。手动隐藏保持隐藏。"),
            ["Drag the example header · close button dims this example"] = ("", "", "拖动示例标题栏 · 关闭按钮仅淡化此示例"),
            ["Drag the grip to arrange your widgets. Switch any widget on or off."] = ("", "", "拖动把手排列小组件。可单独开关每个组件。"),
            ["Drop files here or add files above."] = ("", "", "把文件拖到这里，或使用上方添加文件。"),
            ["Drop files here. Select files to open or drag out."] = ("", "", "把文件拖到这里。选中文件可打开或拖出。"),
            ["Each tool has its own panel above. Enable and reorder Notes, Tasks, Shelf, Clipboard, Calendar, Keep awake and Clean links alongside your other widgets. Saved content is preserved."] = ("", "", "每个工具都有独立面板。启用并排列笔记、任务、文件架、剪贴板、日历、保持唤醒和清理链接。已保存的内容不受影响。"),
            ["Enable history"] = ("", "", "启用历史记录"),
            ["Export diagnostics report"] = ("", "", "导出诊断报告"),
            ["Export layout"] = ("", "", "导出布局"),
            ["Fetching lyrics…"] = ("", "", "正在获取歌词…"),
            ["Focus sessions run in NabyScape and do not change Windows Do Not Disturb."] = ("", "", "专注会话在 NabyScape 内运行，不会更改 Windows 的“勿扰”设置。"),
            ["From · local time"] = ("", "", "起 · 本地时间"),
            ["Fullscreen: "] = ("", "", "全屏："),
            ["Hardware has not been scanned yet."] = ("", "", "尚未扫描硬件。"),
            ["Hermes API address"] = ("", "", "Hermes API 地址"),
            ["Hey, I'm here."] = ("", "", "嘿，我在。"),
            ["Hide / show"] = ("", "", "隐藏 / 显示"),
            ["Higher confidence reduces accidental activation. If your phrase is missed, lower it or try a phrase suited to the selected Windows language."] = ("", "", "置信度越高越不易误触发。如果唤醒词没被识别，可调低或换一个适合所选 Windows 语言的短语。"),
            ["History is off. Enable it in Settings → Controls."] = ("", "", "历史记录已关闭。可在“设置 → 控件”中启用。"),
            ["History is off. Enable it to save the text and images you copy next, only on this device."] = ("", "", "历史记录已关闭。启用后仅在本机保存你接下来复制的文字和图片。"),
            ["Horizontal · %"] = ("", "", "水平 · %"),
            ["Horizontal position percent"] = ("", "", "水平位置百分比"),
            ["How should Naby hear and speak?"] = ("", "", "Naby 应如何听与说？"),
            ["How would you like to use Naby?"] = ("", "", "你想怎么使用 Naby？"),
            ["Image · just now"] = ("", "", "图片 · 刚刚"),
            ["Image support: not tested. Turning Image input on does not verify model support."] = ("", "", "图像支持：未测试。开启图像输入不会验证模型支持情况。"),
            ["Image understanding depends on the model configured in Hermes. The agent/model list is not a list of all underlying LLMs; change the agent’s LLM in Hermes."] = ("", "", "图像理解取决于 Hermes 中配置的模型。代理/模型列表并非全部底层大模型；请在 Hermes 中更换代理使用的模型。"),
            ["Import layout"] = ("", "", "导入布局"),
            ["In the compact media panel, choose the speaker button for volume and mute. The mixer icon opens Apps or Outputs; the chevron opens devices and microphone controls. Choose the media source button to switch playing apps. Tab to a button and press Enter or Space; Esc closes its popover."] = ("", "", "在紧凑媒体面板中，扬声器按钮调节音量与静音；混音器图标打开应用或输出；箭头打开设备与麦克风控制；媒体源按钮切换正在播放的应用。用 Tab 定位按钮后按 Enter 或空格；Esc 关闭弹出层。"),
            ["Includes app and runtime versions, architecture, coarse storage and service status, and up to 64 controlled diagnostic events. No usernames, paths, endpoints, models, device names, keys, conversations, screenshots, audio or saved profile content are included."] = ("", "", "包含应用与运行时版本、架构、粗粒度存储与服务状态，以及最多 64 条受控诊断事件。不含用户名、路径、接口地址、模型、设备名、密钥、对话、截图、音频或已保存的配置内容。"),
            ["Includes appearance, layout, widget order and gestures. Personal notes, shortcuts and startup settings are excluded."] = ("", "", "包含外观、布局、小组件顺序与手势。不含个人笔记、快捷方式和启动设置。"),
            ["Install folder"] = ("", "", "安装文件夹"),
            ["Install NabyScape"] = ("", "", "安装 NabyScape"),
            ["Installed apps"] = ("", "", "已安装的应用"),
            ["Keep your connection changes?"] = ("", "", "保留你的连接更改？"),
            ["Launch NabyScape for this Windows user when you sign in. You can turn this off at any time."] = ("", "", "登录 Windows 时为当前用户启动 NabyScape。随时可以关闭。"),
            ["Leave empty for the default profile or a complete profile URL. With shared multi-profile routing enabled in Hermes, a name adds /p/name/v1/. Use that profile’s own key. Separate profile ports can also be pasted directly."] = ("", "", "默认配置可留空，或填写完整配置地址。Hermes 启用共享多配置路由时，填名称会追加 /p/name/v1/，并使用该配置自己的密钥。独立配置端口也可直接粘贴。"),
            ["Leaves a small edge at the top when Chrome or another app fills this display. Move the pointer to that edge to reveal the preview. Manual hide still hides the whole island."] = ("", "", "当 Chrome 等应用占满此屏幕时在顶部保留一条小边缘。将指针移到该边缘即可显示预览。手动隐藏仍会隐藏整个岛。"),
            ["Left and Right use vertical alignment. Top and Bottom use horizontal position below. Floating uses horizontal position and its top offset. The top notch stays attached to the screen edge. Panels stay upright; side and bottom docks use the available work area."] = ("", "", "左/右停靠使用垂直对齐，上/下停靠使用下方水平位置，浮动使用水平位置与顶部偏移。顶部刘海始终贴附屏幕边缘。面板保持直立；侧边与底部 dock 使用可用工作区。"),
            ["Light follows the selected app's measured volume. Soft fades gently; Responsive follows transients; Punchy reacts faster. Sensitivity helps quiet tracks. Your microphone is never used."] = ("", "", "光效跟随所选应用的实测音量。柔和淡入淡出；响应跟随瞬态；强劲反应更快。灵敏度适合安静曲目。绝不使用你的麦克风。"),
            ["Link to clean"] = ("", "", "要清理的链接"),
            ["Live lyrics switches to a waveform when lyrics are unavailable or during marked instrumental breaks. Track details are sent to LRCLIB while visible. None shows idle or your timer without stopping music."] = ("", "", "歌词不可用或标记为间奏时，动态歌词会切换为波形。可见期间曲目信息会发送到 LRCLIB。选择“无”时显示待机或计时器，不打断音乐。"),
            ["Load local timed lyrics…"] = ("", "", "加载本地同步歌词…"),
            ["Loading installed apps…"] = ("", "", "正在加载已安装应用…"),
            ["Local ASR URL"] = ("", "", "本地 ASR 地址"),
            ["Local LRC files can supply timings when the service is unavailable. Imports last for this app session."] = ("", "", "服务不可用时可用本地 LRC 文件提供时间轴。导入仅对本次运行有效。"),
            ["Local TTS URL"] = ("", "", "本地 TTS 地址"),
            ["Lyric text"] = ("", "", "歌词文本"),
            ["Lyrics"] = ("", "", "歌词"),
            ["Media controls depend on support from your media app. Battery appears on devices with a battery. Transparency controls opacity; glass uses a dark gradient and reflections."] = ("", "", "媒体控制取决于媒体应用的支持。电池仅在有电池的设备上显示。透明度控制不透明度；玻璃使用深色渐变与反射。"),
            ["Media icon"] = ("", "", "媒体图标"),
            ["Media source"] = ("", "", "媒体来源"),
            ["Meeting URL"] = ("", "", "会议链接"),
            ["Meeting URL · optional http(s)"] = ("", "", "会议链接 · 可选 http(s)"),
            ["Mic and screen start only when you choose."] = ("", "", "麦克风与屏幕仅在您选择后开启。"),
            ["Mica is an opaque wallpaper/theme-based foundation. Acrylic is a translucent system blur. This illustration is schematic; see the Settings window itself for the active material. Island glass and its shaped corners remain unchanged."] = ("", "", "Mica 是基于壁纸/主题的不透明底材，Acrylic 是半透明系统模糊。此图为示意，实际材质以设置窗口本身为准。岛体玻璃与圆角保持不变。"),
            ["Microphone"] = ("", "", "麦克风"),
            ["Minutes  "] = ("", "", "分钟  "),
            ["Monitoring stops when disabled. If a folder disconnects or becomes inaccessible, toggle monitoring off and on to restart. Folder paths are excluded from layout exports."] = ("", "", "关闭后停止监视。文件夹断开或不可访问时，重新开关监视即可恢复。文件夹路径不包含在布局导出中。"),
            ["Move & resize island"] = ("", "", "移动与调整岛"),
            ["Music, focus, and your everyday tools — always close.\n\nInstalls for this Windows user only. Choose your folder and startup preference below."] = ("", "", "音乐、专注与日常工具——始终触手可及。\n\n仅为当前 Windows 用户安装。请在下方选择安装文件夹与启动偏好。"),
            ["Naby"] = ("", "", "Naby"),
            ["Naby handles chat, voice and the window/display you choose to share. Your Hermes agent keeps its own skills, memory, tools and permissions."] = ("", "", "Naby 负责聊天、语音与你选择的共享窗口/屏幕。Hermes 代理保留自己的技能、记忆、工具与权限。"),
            ["NabyScape reads the alerts Windows already shows from apps such as Claude, ChatGPT or Telegram, checks for new ones every 1.5 seconds while this is on, and keeps them only for this session. Reply buttons from the original notification stay in Windows; use Open app to answer."] = ("", "", "NabyScape 读取 Windows 已显示的应用提醒（如 Claude、ChatGPT 或 Telegram），开启期间每 1.5 秒检查一次，且仅保留至本次会话。原通知的回复按钮仍在 Windows 中，可用“打开应用”回复。"),
            ["New local event"] = ("", "", "新建本地日程"),
            ["Night Drive"] = ("", "", "夜间驾驶"),
            ["No active media sessions.\nPlay something in Spotify or your browser."] = ("", "", "当前没有播放中的媒体会话。\n在 Spotify 或浏览器里播放点什么吧。"),
            ["No downloaded speech models on this PC."] = ("", "", "本机没有已下载的语音模型。"),
            ["No events for this day."] = ("", "", "这一天没有日程。"),
            ["No events on this day"] = ("", "", "当天没有日程"),
            ["No matching commands or shortcuts."] = ("", "", "没有匹配的命令或快捷方式。"),
            ["No models selected yet."] = ("", "", "尚未选择模型。"),
            ["No synced lyrics found. Try another source."] = ("", "", "未找到同步歌词，请换一个来源。"),
            ["No tasks yet. Add one in Tools → Tasks."] = ("", "", "还没有任务。在“工具 → 任务”中添加。"),
            ["No upcoming events"] = ("", "", "暂无即将到来的日程"),
            ["Not connected yet. Check server reads metadata only; it does not start an agent task."] = ("", "", "尚未连接。检查服务器只读取元数据，不会启动代理任务。"),
            ["Not tested on this visit."] = ("", "", "本次未测试。"),
            ["Not tested yet."] = ("", "", "尚未测试。"),
            ["Notch shows a compact indicator. Hover or click for details. Manually hidden islands use Windows instead. Volume and brightness take priority; panels and editors stay undisturbed. The notification center keeps this session's last 50 alerts; nothing is saved to disk."] = ("", "", "刘海显示紧凑指示器，悬停或点击查看详情。手动隐藏时改用 Windows 提示。音量与亮度优先；面板和编辑器不受打扰。通知中心保留本次会话最近 50 条提醒，不写入磁盘。"),
            ["Nothing captured yet"] = ("", "", "还没有捕获内容"),
            ["Nothing playing"] = ("", "", "未在播放"),
            ["Off"] = ("", "", "关"),
            ["Off by default. Capture starts only when enabled. Turning it off clears saved history and images. Pause and pin items in Tools → Clipboard."] = ("", "", "默认关闭，启用后才开始记录。关闭会清空已保存的历史与图片。可在“工具 → 剪贴板”暂停和置顶条目。"),
            ["Off by default. Watches this folder only, never subfolders. Existing files are ignored. A final name, readable file and stable size for two seconds suggest an arrival; this cannot always prove a browser finished downloading. Originals stay in place. Drag a burst of files together, Show in folder, or Add to shelf (40-item limit)."] = ("", "", "默认关闭。仅监视此文件夹，不含子文件夹，忽略已有文件。文件名完整、可读且大小稳定两秒即视为新文件，但这不一定代表浏览器下载完成。原文件保持不动。可整批拖动、“在文件夹中显示”或“添加到文件架”（上限 40 项）。"),
            ["Off disconnects Windows media sessions and releases track artwork. It leaves playback in your music app untouched."] = ("", "", "关闭会断开 Windows 媒体会话并释放曲目封面，但不会影响音乐应用中的播放。"),
            ["On"] = ("", "", "开"),
            ["Online voice"] = ("", "", "在线语音"),
            ["Open "] = ("", "", "打开 "),
            ["Open Hermes → API server, enable it, and set an API_SERVER_KEY for your profile. Start or restart the gateway with hermes gateway. Your model/provider must already be configured in Hermes. Webhooks are for external events."] = ("", "", "打开 Hermes → API server，启用并为你的配置设置 API_SERVER_KEY。用 hermes gateway 启动或重启网关。模型/服务商需先在 Hermes 中配置好。Webhook 用于外部事件。"),
            ["Open island"] = ("", "", "打开岛"),
            ["Open it from the bell in the island panel, the tray menu, or Ctrl+K → Notifications. Windows delivery follows your Windows notification preferences."] = ("", "", "从岛面板的铃铛、托盘菜单或 Ctrl+K → 通知打开。Windows 通知投递遵循你的 Windows 通知偏好。"),
            ["Open meeting"] = ("", "", "打开会议"),
            ["Open mixer to load audio devices."] = ("", "", "打开混音器以加载音频设备。"),
            ["Open Settings"] = ("", "", "打开设置"),
            ["Open setup guide"] = ("", "", "打开设置指南"),
            ["Open volume mixer"] = ("", "", "打开音量混音器"),
            ["Open-Meteo"] = ("", "", "Open-Meteo"),
            ["OpenAI Realtime and Gemini Live use different protocols. Model access and charges depend on your provider. No microphone or screen is opened by saving."] = ("", "", "OpenAI Realtime 与 Gemini Live 使用不同协议。模型访问与计费取决于你的服务商。保存不会打开麦克风或屏幕。"),
            ["Optional Hermes profile name"] = ("", "", "可选的 Hermes 配置名称"),
            ["Output selection changes the Windows default device. Microphone mute is available from the audio menu."] = ("", "", "输出选择会更改 Windows 默认设备。麦克风静音可在音频菜单中使用。"),
            ["Outputs"] = ("", "", "输出设备"),
            ["Overview shows CPU, memory and uptime. Switch tabs for network, storage or processes. Sampling stops when Status is hidden."] = ("", "", "概览显示 CPU、内存与运行时长。可切换网络、存储或进程标签。隐藏状态页时停止采样。"),
            ["Point to a setting to explore it"] = ("", "", "指向某个设置即可查看说明"),
            ["Power plan"] = ("", "", "电源计划"),
            ["Preview a link without common tracking. Copy it when you're ready."] = ("", "", "预览去除常见跟踪参数的链接。准备好后复制即可。"),
            ["Preview notch notification"] = ("", "", "预览刘海通知"),
            ["Preview note draft"] = ("", "", "预览笔记草稿"),
            ["Preview sound"] = ("", "", "试听提示音"),
            ["Primary uses the main display. Selected uses the display below, falling back to Primary if disconnected. Follow cursor slides after 250 ms on another display; it waits during interaction and manual hide. Detached previews stay where placed. Example: move to a second display, pause, then continue working."] = ("", "", "“主显示器”使用主屏；“选定”使用下方所选显示器，断开时回退主屏；“跟随光标”在 250 毫秒后滑向另一显示器，交互与手动隐藏期间等待。分离预览保持原位。示例：移到第二块屏，暂停后再继续工作。"),
            ["Provider name"] = ("", "", "服务商名称"),
            ["Quick note"] = ("", "", "快速笔记"),
            ["Quiet hours silence Naby notifications and completion sounds. A matching start and end disables the schedule. Windows notifications from other apps are unaffected."] = ("", "", "免打扰时段会静音 Naby 通知与完成提示音。开始与结束相同则禁用该计划。其他应用的 Windows 通知不受影响。"),
            ["Quit"] = ("", "", "退出"),
            ["RAM"] = ("", "", "内存"),
            ["Reading selected app…"] = ("", "", "正在读取所选应用…"),
            ["Real audio levels drive the bars. Quiet playback can use decorative motion when no level is available."] = ("", "", "波形条由真实音量驱动。无电平数据时，安静播放可使用装饰性动效。"),
            ["Realtime WebSocket URL"] = ("", "", "实时 WebSocket 地址"),
            ["Refresh diagnostics preview"] = ("", "", "刷新诊断预览"),
            ["Refresh plans"] = ("", "", "刷新电源计划"),
            ["Remove listening or speaking models you no longer need. Matching download caches are removed too. Shared speech engines stay installed. You can reinstall a model from Automatic setup."] = ("", "", "移除不再需要的听/说模型，对应的下载缓存也会删除。共享语音引擎保持安装。之后可从“自动设置”重新安装。"),
            ["Replay transition"] = ("", "", "重播过渡动画"),
            ["Resume notifications"] = ("", "", "恢复通知"),
            ["Retry lyrics"] = ("", "", "重试歌词"),
            ["Retry save"] = ("", "", "重试保存"),
            ["Review the preview before copying or exporting. Nothing is uploaded automatically."] = ("", "", "复制或导出前请先检查预览内容。不会自动上传任何信息。"),
            ["Same PC: http://127.0.0.1:8642/v1/. Remote server: use its public HTTPS address, or forward its port to localhost. Naby does not install or start Hermes for you."] = ("", "", "本机：http://127.0.0.1:8642/v1/。远程服务器：使用其公网 HTTPS 地址，或将端口转发到本机。Naby 不会替你安装或启动 Hermes。"),
            ["Sampling system information…"] = ("", "", "正在采集系统信息…"),
            ["Save event"] = ("", "", "保存日程"),
            ["Save this provider before continuing, discard its changes, or keep editing."] = ("", "", "请先保存该服务商再继续、放弃其更改，或继续编辑。"),
            ["Saved locally"] = ("", "", "已保存到本地"),
            ["Saved on this device. Times use your Windows time zone."] = ("", "", "保存在此设备。时间使用 Windows 时区。"),
            ["Say a phrase to open Naby voice and start your selected voice connection. Detection uses an installed Windows speech recognizer, separately from your ASR/TTS models."] = ("", "", "说出短语即可打开 Naby 语音并启动所选语音连接。识别使用已安装的 Windows 语音识别器，与你的 ASR/TTS 模型相互独立。"),
            ["Scroll anywhere on a preview to browse. Click to open its panel."] = ("", "", "在预览上滚动即可浏览。点击打开对应面板。"),
            ["Search"] = ("", "", "搜索"),
            ["Search city or town…"] = ("", "", "搜索城市或城镇…"),
            ["Search installed apps"] = ("", "", "搜索已安装应用"),
            ["Search sends the title and artist to your selected source."] = ("", "", "搜索会把曲名与歌手发送到你选择的来源。"),
            ["Search synced lyrics"] = ("", "", "搜索同步歌词"),
            ["Select a listening model"] = ("", "", "选择听写模型"),
            ["Select a speaking model"] = ("", "", "选择朗读模型"),
            ["Select files, then drag them out together"] = ("", "", "选中文件后一起拖出"),
            ["Selected"] = ("", "", "已选"),
            ["Selected "] = ("", "", "已选 "),
            ["Selected tab"] = ("", "", "选中的标签"),
            ["Sends a generated color sample to the saved provider. No personal image is sent. This may use provider credits; Hermes may run an agent task. Image replies are a separate capability."] = ("", "", "向已保存的服务商发送一张生成的颜色样本，不含个人图像。可能消耗服务商额度；Hermes 可能运行代理任务。图像回复是独立能力。"),
            ["Set up AI"] = ("", "", "设置 AI"),
            ["Shared memory: "] = ("", "", "共享内存："),
            ["Shared notes document"] = ("", "", "共享笔记文档"),
            ["Shortcut destination"] = ("", "", "快捷方式目标"),
            ["Single color uses the cover's dominant hue. Cover blend mixes two album colors. Custom blend uses both chosen colors. Spread and height can extend light across the whole panel; closed-dock light has its own switch. Idle and tucked docks always stay black."] = ("", "", "“单色”使用封面主色调；“封面混合”混合两种专辑色；“自定义混合”使用所选两色。扩散与高度可让光覆盖整个面板；收起状态光效有独立开关。待机与收起的 dock 始终为黑色。"),
            ["Skip setup"] = ("", "", "跳过设置"),
            ["Smart clipboard"] = ("", "", "智能剪贴板"),
            ["Snooze "] = ("", "", "稍后提醒 "),
            ["Snooze ends automatically. It does not stop Timer or Focus. Resume removes the snooze; any scheduled quiet hours still apply."] = ("", "", "稍后提醒会自动结束，不会停止计时器或专注。恢复通知即取消稍后提醒；计划中的免打扰时段仍然生效。"),
            ["Song title"] = ("", "", "曲名"),
            ["Speaker ID"] = ("", "", "说话人 ID"),
            ["Speaking models"] = ("", "", "朗读模型"),
            ["Spectrum separates real bass, midrange and treble from the selected media app's active output. Other apps sharing that output can influence the bands. Muting the selected app silences the display. Output samples stay in memory; microphone capture is never used. Amplitude history remains the fallback for unsupported output formats."] = ("", "", "频谱从所选媒体应用的输出中分离真实低/中/高频。共用该输出的其他应用会影响频段。静音所选应用即停止显示。采样仅保存在内存中，绝不使用麦克风采集。不支持的输出格式回退为振幅历史。"),
            ["Spectrum shows 25 real frequency bands from low to high. If output capture is unavailable, the waveform uses measured amplitude history. Sensitivity changes the visible range without adding artificial beats."] = ("", "", "频谱显示从低到高的 25 个真实频段。无法捕获输出时，波形使用实测振幅历史。灵敏度只改变可视范围，不会添加人工节拍。"),
            ["Staged files stay in their original location."] = ("", "", "暂存的文件保留在原位置。"),
            ["Start     +5 min"] = ("", "", "开始     +5 分钟"),
            ["Start keep awake"] = ("", "", "开始保持唤醒"),
            ["Start with Windows"] = ("", "", "随 Windows 启动"),
            ["Still keeps the glow in place. Breathe and Drift add gentle motion during playback. Audio response works with all three. Motion stops when paused, hidden, tucked, or Reduce motion is on; Live activity also controls audio response."] = ("", "", "“静止”保持光晕不动；“呼吸”与“漂移”在播放时加入轻微动效。三种模式都支持音频响应。暂停、隐藏、收起或开启减弱动态时停止；实时活动也控制音频响应。"),
            ["Stop all microphones"] = ("", "", "关闭所有麦克风"),
            ["Stop keep awake"] = ("", "", "停止保持唤醒"),
            ["Storage recovery"] = ("", "", "存储恢复"),
            ["Suggested model names; this list does not mean they are installed. The model must match the one loaded by your local server."] = ("", "", "以下为建议的模型名称，不代表已安装。模型必须与本地服务器加载的名称一致。"),
            ["Suggestions are memory budgets, not measured speed or a quality ranking. Other apps and local chat share RAM/VRAM. New compatible pack versions arrive through Naby updates. Native TTS uses CPU to leave VRAM available for ASR. AMD/Intel GPUs use the CPU path. AI replies still use your selected chat provider or Hermes."] = ("", "", "建议值为内存预算，不代表实测速度或质量排名。其他应用与本地聊天会共享内存/显存。新的兼容语音包随 Naby 更新提供。本地 TTS 使用 CPU 以便为 ASR 保留显存。AMD/Intel 显卡走 CPU 路径。AI 回复仍使用你选择的聊天服务商或 Hermes。"),
            ["Swipe empty space or use Shift+wheel to switch panels. Long lists keep vertical scrolling. Keyboard: Ctrl+Tab."] = ("", "", "在空白处滑动或用 Shift+滚轮切换面板。长列表保持垂直滚动。键盘：Ctrl+Tab。"),
            ["System information unavailable. Retrying…"] = ("", "", "系统信息不可用，正在重试…"),
            ["Tap a provider to fetch lyrics, then choose a synced version."] = ("", "", "点击服务商获取歌词，然后选择一个同步版本。"),
            ["Templates are starting points, not hardware guarantees. Speech services run separately and use additional RAM/VRAM. A local chat model shares that budget."] = ("", "", "模板只是起点，不是硬件保证。语音服务独立运行并占用额外内存/显存，本地聊天模型共享该预算。"),
            ["Temporarily prevent automatic sleep. Your normal power settings return when this stops or NabyScape quits."] = ("", "", "暂时阻止自动睡眠。停止或退出 NabyScape 后恢复正常电源设置。"),
            ["Tests use your saved setup. Microphone tests record four seconds on this PC; transcription is sent only to your configured speech service, never to the chat model. Play sample speaks a fixed sentence. Nothing is added to chat or saved as an audio file."] = ("", "", "测试使用已保存的配置。麦克风测试在本机录制四秒；转写仅发送到已配置的语音服务，绝不会发给聊天模型。播放示例朗读固定句子。不会加入聊天，也不会保存音频文件。"),
            ["The connector uses stdio and a pipe restricted to your Windows account. There is no listening network port. The Windows setup is for Hermes on this PC; the WSL setup requires Windows executable interop in WSL on the same PC."] = ("", "", "连接器使用 stdio 与仅限当前 Windows 账户的管道，不监听任何网络端口。Windows 安装面向本机 Hermes；WSL 安装需要同机 WSL 中的 Windows 可执行互操作。"),
            ["The existing local errors.log may contain private details and is never included in this report."] = ("", "", "本地 errors.log 可能包含隐私细节，绝不包含在本报告中。"),
            ["The lyrics icon beside playback controls toggles this preference. Slide follows each new line; Focus softly emphasizes it; Karaoke sweeps across the line using line timing. Reduce Motion keeps the text static. Tab to the lyrics button and press Space to show or hide."] = ("", "", "播放控制旁的歌词图标可切换此偏好。滑动跟随新行；专注柔和强调当前行；卡拉OK按行时间扫过。减弱动态时文字保持静止。Tab 定位歌词按钮后按空格显示或隐藏。"),
            ["These files are no longer available."] = ("", "", "这些文件已不可用。"),
            ["Timer and Focus play this sound directly when their per-type notification toggle is on. It uses the current Windows output; Off silences it. Custom WAV files must be under 10 MB and at most 15 seconds. File paths are kept locally and excluded from layout exports."] = ("", "", "计时器与专注在各自通知开关打开时直接播放此声音，使用当前 Windows 输出设备；“关”为静音。自定义 WAV 需小于 10 MB 且不超过 15 秒。文件路径仅保存在本地，不包含在布局导出中。"),
            ["Title"] = ("", "", "标题"),
            ["Today"] = ("", "", "今天"),
            ["Toggle calendar month"] = ("", "", "切换日历月份"),
            ["Try the tabs · Shift+wheel on the real panel"] = ("", "", "试试标签切换 · 实际面板可用 Shift+滚轮"),
            ["Tuck / Return to automatic"] = ("", "", "收起 / 恢复自动"),
            ["Turn off to suppress automatic browser previews, including YouTube hover playback. Unknown Windows media identities are also suppressed. Manual island hover and playback controls still work."] = ("", "", "关闭后不再自动预览浏览器媒体（含 YouTube 悬停播放），未知 Windows 媒体标识也会被抑制。手动悬停与播放控制不受影响。"),
            ["Undo"] = ("", "", "撤销"),
            ["Uninstall can remove downloaded speech models, caches, history and saved connections too."] = ("", "", "卸载时可一并移除已下载的语音模型、缓存、历史与已保存的连接。"),
            ["Uninstall NabyScape…"] = ("", "", "卸载 NabyScape…"),
            ["Until"] = ("", "", "直到"),
            ["Use essentials"] = ("", "", "使用精简模式"),
            ["Use media source "] = ("", "", "使用媒体源 "),
            ["Use NVIDIA GPU for Whisper when available · CPU fallback included"] = ("", "", "可用时为 Whisper 使用 NVIDIA GPU · 含 CPU 回退"),
            ["Use NVIDIA GPU when supported · CPU fallback included"] = ("", "", "支持时使用 NVIDIA GPU · 含 CPU 回退"),
            ["Use stronger titles without changing body text, timestamps or counters. Each option is independent; the adjacent preview shows both weights."] = ("", "", "加粗标题样式，不改变正文、时间戳与计数。各选项相互独立；旁边的预览同时显示两种字重。"),
            ["Use Windows Downloads"] = ("", "", "使用 Windows 下载文件夹"),
            ["Use your own model files"] = ("", "", "使用自己的模型文件"),
            ["Uses the island's shared system sample."] = ("", "", "使用岛共享的系统采样。"),
            ["Uses the realtime model and voice saved for this provider. API usage may be billed by your provider."] = ("", "", "使用该服务商保存的实时模型与音色，API 用量可能由服务商计费。"),
            ["Uses the same order as Your widgets. Turn this off to choose a separate hover order below."] = ("", "", "使用与“你的小组件”相同的顺序。关闭后可在下方单独设置悬停顺序。"),
            ["Uses your default installed Windows SAPI voice. No TTS server is needed. Voice and language availability depends on Windows."] = ("", "", "使用系统默认的 Windows SAPI 语音，无需 TTS 服务器。音色与语言可用性取决于 Windows。"),
            ["Utilization uses the busiest GPU engine. Counter IDs do not identify the model above."] = ("", "", "利用率取最繁忙的 GPU 引擎。计数器 ID 不能对应上方的模型。"),
            ["Version "] = ("", "", "版本 "),
            ["Vertical dock position"] = ("", "", "Dock 垂直位置"),
            ["View "] = ("", "", "查看 "),
            ["Voice & wake word"] = ("", "", "语音与唤醒词"),
            ["Voice models for your PC"] = ("", "", "本机语音模型"),
            ["Voice name"] = ("", "", "音色名称"),
            ["Voice suggestions are for Kokoro. For Piper or other servers, paste that server's model and voice IDs."] = ("", "", "建议音色适用于 Kokoro。Piper 或其他服务器请粘贴其模型与音色 ID。"),
            ["Volume"] = ("", "", "音量"),
            ["Wake phrase"] = ("", "", "唤醒短语"),
            ["Weather city search"] = ("", "", "天气城市搜索"),
            ["When a document is unreadable or from a newer version, it stays protected from automatic saves. Temporary defaults may be shown. Quit NabyScape and preserve the original JSON file and its matching .schema.json sidecar before recovery. Use a compatible app version, or restore a known-good matching document and schema backup. For a legacy backup without a sidecar, preserve and move aside the current sidecar too. Keep the original and migration backup until recovery is verified. Reset preferences does not unlock protected documents."] = ("", "", "当文档无法读取或来自更新版本时，将受到保护而不被自动保存，期间可能显示临时默认值。恢复前请退出 NabyScape，并保留原 JSON 文件与其对应的 .schema.json 边车文件。请使用兼容的应用版本，或恢复一对已知良好的文档与 schema 备份。对于没有边车文件的旧备份，也请保留并移开当前边车。在确认恢复成功前，请保留原件与迁移备份。“重置偏好设置”不会解锁受保护的文档。"),
            ["Windows sound settings"] = ("", "", "Windows 声音设置"),
            ["Windows voices are managed in Windows Settings. Model files you imported from another folder stay in their original location and are not deleted here."] = ("", "", "Windows 语音在 Windows 设置中管理。从其他文件夹导入的模型文件保留在原位置，不会在此删除。"),
            ["Working sets can share memory; they do not sum to total RAM usage."] = ("", "", "工作集之间可能共享内存，不能相加得出总内存占用。"),
            ["You can reopen this guide from Settings > General."] = ("", "", "可随时从“设置 > 常规”重新打开本引导。"),
            ["You choose when to use the microphone or share your screen. Hermes manages its own tools and permissions."] = ("", "", "何时使用麦克风或共享屏幕由你决定。Hermes 自行管理其工具与权限。"),
            ["Your AI, your provider"] = ("", "", "你的 AI，你的服务商"),
            ["Your chat connection"] = ("", "", "你的聊天连接"),
            ["Your daily outlook starts with a city. Search above to get started."] = ("", "", "选个城市，开始你的每日天气。在上方搜索即可。"),
            ["Your Hermes, inside Naby"] = ("", "", "Naby 内置你的 Hermes"),
            ["Your key is stored securely in Windows. Leave it blank to keep the saved key."] = ("", "", "密钥安全地存储在 Windows 中。留空则保留已保存的密钥。"),
            ["Your next copied item will appear here."] = ("", "", "下一次复制的内容会出现在这里。"),
            ["Your tasks appear here. Add them in Tools → Tasks."] = ("", "", "你的任务会显示在这里。可在“工具 → 任务”中添加。"),
            ["1 · Keep NabyScape running with AI and widget navigation enabled.\n2 · Merge the copied nabyscape entry under mcp_servers in your Hermes config.yaml. Keep your other server entries.\n3 · Restart Hermes or reload its MCP tools. Ask Hermes to use naby_list_widget_pages or naby_navigate_widget."] = ("", "", "1 · 保持 NabyScape 运行，并启用 AI 与小组件导航。\n2 · 将复制的 nabyscape 条目合并到 Hermes config.yaml 的 mcp_servers 下，保留其他服务器条目。\n3 · 重启 Hermes 或重载其 MCP 工具，并让 Hermes 使用 naby_list_widget_pages 或 naby_navigate_widget。"),
            ["2 · Start your local speech service"] = ("", "", "2 · 启动你的本地语音服务"),
            ["3 · Check services, then save"] = ("", "", "3 · 检查服务后保存"),
            ["3 files · drop to stage"] = ("", "", "3 个文件 · 拖入暂存"),
            ["Ask “Open Weather”, “Show my tasks” or “Next widget page”. A tool-capable chat or voice model can list enabled pages and open one. Navigation changes the visible page only; it does not read or edit widget contents or start activities."] = ("", "", "试试“打开天气”“显示我的任务”或“下一页小组件”。具备工具能力的聊天或语音模型可以列出已启用页面并打开其中一页。导航仅切换可见页面，不会读取或编辑小组件内容，也不会启动活动。"),
            ["Choose Album artwork in Audio. Click to play/pause; hold 500 ms to choose a session. Keyboard: Ctrl+Space for playback, Ctrl+M for sessions."] = ("", "", "在“音频”中选择专辑封面。点击播放/暂停；长按 500 毫秒选择会话。键盘：Ctrl+Space 播放，Ctrl+M 切换会话。"),
            ["Choose models already on your PC. Files stay in their current location; Naby saves their paths. Only missing speech engines may need downloading."] = ("", "", "选择电脑上已有的模型。文件保留原位置，Naby 只保存路径。仅缺失的语音引擎可能需要下载。"),
            ["Clipboard capture and voice listening have separate switches. Turning a widget off preserves your notes, files and timers. Hidden weather and system pages stop their work; audio capture is released when no visual needs it."] = ("", "", "剪贴板记录与语音监听有独立开关。关闭小组件会保留笔记、文件与计时器。隐藏天气与系统页面会停止其工作；无界面需要时释放音频采集。"),
            ["Clipboard history: "] = ("", "", "剪贴板历史："),
            ["Code block"] = ("", "", "代码块"),
            ["Copy HEX    Copy RGB"] = ("", "", "复制 HEX    复制 RGB"),
            ["Counter: "] = ("", "", "计数："),
            ["Essentials shows music, clock, timer and focus. Other widgets stay off until you enable them. Animation quality stays the same."] = ("", "", "精简模式保留音乐、时钟、计时与专注，其他小组件默认关闭。动画质量保持不变。"),
            ["Enabling this keeps the default microphone listening locally while NabyScape runs. After activation, voice uses your chosen provider. End conversation returns to wake listening when enabled. Stop, Hide, screen lock and sleep pause it; resume from Options or the tray. Wake word is off by default."] = ("", "", "启用后 NabyScape 运行期间默认麦克风在本地持续监听。激活后语音使用你选择的服务商。开启时结束对话会回到唤醒监听。停止、隐藏、锁屏与睡眠会暂停；可从选项或托盘恢复。唤醒词默认关闭。"),
            ["Event end date"] = ("", "", "日程结束日期"),
            ["Event end time"] = ("", "", "日程结束时间"),
            ["Event start date"] = ("", "", "日程开始日期"),
            ["Event start time"] = ("", "", "日程开始时间"),
            ["Event title"] = ("", "", "日程标题"),
            ["Example button"] = ("", "", "示例按钮"),
            ["Example controls · changes apply to the app"] = ("", "", "示例控件 · 更改会应用到应用"),
            ["Example detached note"] = ("", "", "示例分离笔记"),
            ["Example files · nothing is added to your shelf"] = ("", "", "示例文件 · 不会加入你的文件架"),
            ["Example items · your clipboard is untouched"] = ("", "", "示例条目 · 不会动你的剪贴板"),
            ["Explicit sleep, locking, and closing the lid remain under Windows control."] = ("", "", "主动睡眠、锁屏与合盖仍由 Windows 控制。"),
            ["Follows the selected app across its active outputs. Spectrum includes other sounds sharing those outputs; Amplitude history reads the selected app level only."] = ("", "", "跟随所选应用在其活动输出上的播放。频谱包含共用该输出的其他声音；振幅历史只读取所选应用的电平。"),
            ["‹   All tools"] = ("", "", "‹   全部工具"),
            ["#8E9AAF · rgb(142, 154, 175)"] = ("", "", "#8E9AAF · rgb(142, 154, 175)"),
            ["Ctrl+K"] = ("", "", "Ctrl+K"),
            ["JSON report (*.json)|*.json"] = ("", "", "JSON report (*.json)|*.json"),
            ["↗  Drop files or drag out"] = ("", "", "↗  放入文件或拖出"),
            ["0 hides the dock completely. Use the tuck shortcut or hover the screen edge to reveal it."] = ("", "", "0 表示完全隐藏 dock。用收起快捷键或悬停屏幕边缘恢复。"),
            ["Album color rises from the bottom and fades into the dark surface. Without artwork, your accent color is used."] = ("", "", "专辑色从底部升起并融入深色底面。无封面时使用你的强调色。"),
            ["An arbitrary ONNX, GGUF or safetensors file cannot run with every engine. Choose the matching exported format and support files. Model memory use and accuracy cannot be confirmed from the folder alone. For another runtime, use External ASR + TTS."] = ("", "", "任意的 ONNX、GGUF 或 safetensors 文件并非所有引擎都能运行，请选择匹配的导出格式与支持文件。仅凭文件夹无法确认模型内存占用与精度。如需其他运行时，请使用外部 ASR + TTS。"),
            ["An existing saved key is kept only for the exact same Hermes address/profile. Keys stay in Windows Credential Manager; they are not put in chat or copied by the setup template."] = ("", "", "已保存的密钥仅在 Hermes 地址/配置完全相同时沿用。密钥保存在 Windows 凭据管理器中，不会进入聊天，也不会被设置模板复制。"),
            ["Automatic finds timed lyrics across public catalogues using the current title, artist and duration. Choose a source from the Lyrics menu. Romaji is generated offline; availability varies by track."] = ("", "", "“自动”用当前曲名、歌手与时长在公开曲库中查找同步歌词。可在歌词菜单选择来源。罗马音离线生成，可用性因曲目而异。"),
            ["Automatic readings may differ for names or creative kanji. Timing stays unchanged."] = ("", "", "人名或创意汉字的自动读音可能有差异，时间轴保持不变。"),
            ["Brightness indication requires Windows display-brightness events. Unsupported displays cannot report changes; no brightness is adjusted."] = ("", "", "亮度指示依赖 Windows 亮度事件。不支持的显示器无法报告变化，也不会调节亮度。"),
            ["Choose WAV…"] = ("", "", "选择 WAV…"),
            ["Color buttons, input fields, selected tabs and mini-window outlines. Open a picker to see the change beside these controls. Island and accent colors are separate."] = ("", "", "作用于按钮、输入框、选中标签与迷你窗口描边。打开取色器即可在控件旁看到变化。岛体色与强调色相互独立。"),
            ["Compact indicators expire after this time. Open details and active interactions keep the current notification available."] = ("", "", "紧凑指示器在此时间后消失。打开详情或正在交互时，当前通知保持可见。"),
            ["Connect your own Hermes API server. Its tools, skills and memory stay in Hermes. Naby handles chat, voice and the sharing source you select. Use Connect Hermes for the setup guide."] = ("", "", "连接你自己的 Hermes API 服务器。工具、技能与记忆保留在 Hermes 中。Naby 负责聊天、语音与你选择的共享来源。设置指南见“连接 Hermes”。"),
            ["Connect your own provider or Hermes whenever you're ready. Voice starts only when you choose it."] = ("", "", "准备好后随时连接你自己的服务商或 Hermes。语音仅在您选择后开启。"),
            ["Copy cleaned link"] = ("", "", "复制清理后的链接"),
            ["Count elapsed time with Start, Pause, Resume and Reset. Sleep is counted, and the session survives restart. Tab to a button and press Space or Enter. Enable Stopwatch above to show it in Focus."] = ("", "", "用开始、暂停、继续与重置累计用时。睡眠时间计入，会话可在重启后恢复。Tab 定位按钮后按空格或回车。在上方启用秒表即可在专注页显示。"),
            ["CPU · 60 second window · 2 second samples"] = ("", "", "CPU · 60 秒窗口 · 2 秒采样"),
            ["Drag the grip to place a mini window, or choose Detach. Supports Music, Timer, Focus, Calendar, Notes, Shelf and System. Closing it keeps music and sessions running."] = ("", "", "拖动把手放置迷你窗口，或选择“分离”。支持音乐、计时、专注、日历、笔记、文件架与系统。关闭窗口不会中断音乐与会话。"),
            ["Drag the top grip to reposition the island. Drag either lower corner to resize the current state: closed, hover or open panel. Position and each size are saved separately. Hold Alt while the island is focused to reveal handles temporarily; Esc cancels a drag. Dragging down detaches a notch into a pill; a drag that begins as a notch can snap back to the top edge."] = ("", "", "拖动顶部把手移动岛；拖动两个下角调整当前形态（收起/悬停/面板）的大小。位置与各形态尺寸分别保存。岛获得焦点时按住 Alt 可临时显示把手；Esc 取消拖动。向下拖动可把刘海分离为胶囊；从刘海开始的拖动也可吸附回顶部边缘。"),
            ["Drag to reorder "] = ("", "", "拖动排序 "),
            ["Dragging a lower panel corner sets a manual height. With Fit height off, the height limit becomes the fixed panel height; content scrolls inside it."] = ("", "", "拖动面板下角可设定手动高度。关闭“自适应高度”后，高度上限即固定面板高度，内容在内部滚动。"),
            ["Enable image input if this model can understand attached images, PDF pages, video frames and shared windows. Agent tools are managed in Hermes; Naby does not execute local actions."] = ("", "", "若模型能理解附件图像、PDF 页面、视频帧与共享窗口，可开启图像输入。代理工具由 Hermes 管理；Naby 不执行本地操作。"),
            ["Enable image replies only for compatible image models: Responses image generation, Gemini image models or Chat Completions endpoints with image output. Hermes uses its own configured image tools. Image links returned in chat can always be displayed."] = ("", "", "仅为兼容的图像模型开启图像回复：Responses 图像生成、Gemini 图像模型或支持图像输出的 Chat Completions 端点。Hermes 使用其自带的图像工具。聊天中返回的图片链接始终可以显示。"),
            ["NabyScape"] = ("", "", "NabyScape"),
            ["Uses the island’s shared system sample."] = ("", "", "使用岛共享的系统采样。"),
            ["Voice suggestions are for Kokoro. For Piper or other servers, paste that server’s model and voice IDs."] = ("", "", "建议音色适用于 Kokoro。Piper 或其他服务器请粘贴其模型与音色 ID。"),
        };
}
